\documentclass[border=5mm]{standalone}
\usepackage{pgfplots}
\usetikzlibrary {arrows.meta}
\usepackage{tikz}

\begin{document}

\definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
\definecolor{orangepeel}{rgb}{0.902, 0.624, 0}
\definecolor{lightyellow}{rgb}{0.953,0.882,0.388}
\definecolor{darkgreen}{rgb}{0.271, 0.608, 0.463}
\definecolor{lightblue}{rgb}{0.484,0.702,0.894}
\definecolor{rustred}{rgb}{0.784,0.392,0.149}
\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}

\pagestyle{empty}
\begin{tikzpicture}[scale=1.25, rotate=0]

\def\nsamples{24}

%%% Change this:
\def\mr{5} % Marks on axes (Rho)

\begin{axis}[
		scale=1,
		clip=false,
		view={120}{20},
		hide axis,
		xmin=-0.5,xmax=2.5,
		ymin=-1.5,ymax=1.5,
		zmin=-1.3,zmax=1.3,
	]

% Axes
\def\axwidth{0.6}

% Lower bound label
\draw[<                  -] (axis cs:0.5,0.5,-0.125) to[bend right=40] (axis cs:0.5,1,-0.45) node[right] {\footnotesize $z=0$};

% Surface
\plot3[
	surf,
	shader = interp, 
	opacity=1,
	samples = \nsamples,
	samples y=\nsamples,
	draw=lightgray, ultra thin,
	colormap={custom}{color(0)=(deepskyblue!70) color(1)=(deepskyblue!10)},
	z buffer=sort, domain=0:2, y domain=0:360]
({x*cos(y)/2}, {x*sin(y)/2}, {(2-x)});

% Ellipse
\draw[line width=\axwidth/2, deepskyblue, dashed]plot[domain=130:290, samples=360, variable=\x] (axis cs:{1*cos(\x)},{1*sin(\x)},0);
\draw[line width=\axwidth*1.5, deepskyblue]plot[domain=-70:130, samples=360, variable=\x] (axis cs:{1*cos(\x)},{1*sin(\x)},0);

% X
\draw[line width=\axwidth/2, dashed, opacity=0.5] (axis cs:-1.5,0,0) -- (axis cs:1,0,0);
\draw[line width=\axwidth, -stealth] (axis cs:1,0,0) -- (axis cs:2,0,0) node[left, xshift=4pt, yshift=-3pt] {\scriptsize $x$}; 	

% Y
\draw[line width=\axwidth] (axis cs:0,-1.5,0) -- (axis cs:0,-1.08,0);
\draw[line width=\axwidth/2, dashed, opacity=0.5] (axis cs:0,-1.1,0) -- (axis cs:0,1,0);
\draw[line width=\axwidth, -stealth] (axis cs:0,1,0) -- (axis cs:0,1.5,0) node[right, yshift=-2pt] {\scriptsize $y$};
% Z
\draw[line width=\axwidth] (axis cs:0,0,-0.5) -- (axis cs:0,0,-0.35);
\draw[line width=\axwidth/2, dashed, opacity=0.5] (axis cs:0,0,-0.35) -- (axis cs:0,0,2);
\draw[line width=\axwidth, -stealth] (axis cs:0,0,2) -- (axis cs:0,0,2.5) node[above] {\scriptsize $z$};  

% Ticks-X
%\node[circle, draw=none, fill=black, inner sep=0.5pt] at (axis cs:-1,0,0) {};
\node[circle, draw=none, fill=black, inner sep=0.5pt] at (axis cs:1,0,0) {};

% Ticks-Y
%\node[circle, draw=none, fill=black, inner sep=0.5pt] at (axis cs:0,-1,0) {};
\node[circle, draw=none, fill=black, inner sep=0.5pt] at (axis cs:0,1,0) {};

% Ticks-Z
\node[circle, draw=none, fill=black, inner sep=0.5pt] at (axis cs:0,0,2) {};

% Upper bound label
\draw[<                  -] (axis cs:0.5,0.5,1.5) to[bend left=40] (axis cs:0.5,1,2) node[right] {\footnotesize $z = 1 - \sqrt{x^2 + y^2}$};

\end{axis}
\end{tikzpicture}
\end{document}

